/**
 * The chatter ranks the platforms actually report, in the order that decides
 * which one wins when somebody holds several — a broadcaster is also a
 * moderator and usually a subscriber.
 *
 * Twitch is the only platform that reports all four. YouTube reports the
 * channel owner, its moderators and its members — a member counts as a
 * subscriber, since that is what they are — and has no VIPs. TikTok reports
 * moderator and subscriber only; Discord messages carry no rank at all.
 * `platforms` says so on each settings row, rather than letting someone
 * enable VIP and wonder why their TikTok chat never lights up.
 *
 * Defaults are Twitch's own badge colours, so a rank reads as itself before
 * anyone touches a picker. Shared with the dock so the badge beside a name and
 * the frame around the message cannot drift apart.
 */
export const CHAT_RANKS = [
  { key: 'broadcaster', label: 'permOwner', fallback: '#E91916', platforms: 'Twitch · YouTube' },
  { key: 'moderator', label: 'permMods', fallback: '#00AD03', platforms: 'Twitch · YouTube · TikTok' },
  { key: 'vip', label: 'permVips', fallback: '#E005B9', platforms: 'Twitch' },
  { key: 'subscriber', label: 'permSubs', fallback: '#8205B3', platforms: 'Twitch · YouTube · TikTok' },
] as const;

/**
 * The platforms whose stream events may appear in the chat, and whether a
 * chat's settings let one through.
 *
 * On unless switched off, the way the server reads the same setting. Saved
 * settings from before YouTube was here do not mention it at all, and "not
 * mentioned" has to mean the default rather than off — or its Super Chats
 * would stay hidden behind a switch that shows as on.
 *
 * Discord is not here: it sends no stream events, and a switch for it only
 * ever looked like it did something.
 */
export const CHAT_EVENT_PLATFORMS = ['twitch', 'youtube', 'tiktok'] as const;
export const chatEventsOn = (prefs: Record<string, boolean> | undefined, platform: string) =>
  (CHAT_EVENT_PLATFORMS as readonly string[]).includes(platform) && prefs?.[platform] !== false;

